var restoreFromCloudCodeString = async (inputStr, workspaceId) => {
	try {
		const cleanStr = inputStr.trim();
		if (!cleanStr) return {
			success: false,
			message: "کۆدەکە بەتاڵە، تکایە کۆدێکی دروست دابنێ"
		};
		let dataObj = null;
		if (cleanStr.startsWith("XP_CLOUD_v2:")) {
			const decodedJson = decodeBase64Utf8(cleanStr.slice(12).trim());
			dataObj = JSON.parse(decodedJson);
		} else if (cleanStr.startsWith("{") || cleanStr.startsWith("[")) dataObj = JSON.parse(cleanStr);
		else try {
			const decoded = decodeBase64Utf8(cleanStr);
			dataObj = JSON.parse(decoded);
		} catch {
			return {
				success: false,
				message: "فۆرماتی کۆدەکە نادروستە یان تێکچووە"
			};
		}
		if (!dataObj || typeof dataObj !== "object") return {
			success: false,
			message: "هیچ داتایەکی گونجاو لەناو کۆدەکەدا نەدۆزرایەوە"
		};
		if (dataObj.months && typeof dataObj.months === "object") for (const [mStr, doc] of Object.entries(dataObj.months)) await saveMonthDoc(mStr, doc, workspaceId);
		else if (Array.isArray(dataObj.m) && dataObj.y) for (let i = 0; i < dataObj.m.length; i++) await saveMonthDoc(`${dataObj.y}-${String(i + 1).padStart(2, "0")}`, dataObj.m[i], workspaceId);
		if (dataObj.g) await setItem("goals", dataObj.g, workspaceId);
		if (dataObj.r) await setItem("rec", dataObj.r, workspaceId);
		if (dataObj.n) await setItem("names", dataObj.n, workspaceId);
		if (dataObj.w) await setItem("wealth", dataObj.w, workspaceId);
		if (dataObj.pl) await setItem("ppl", dataObj.pl, workspaceId);
		if (dataObj.sh) await setItem("shop", dataObj.sh, workspaceId);
		if (dataObj.km) await setItem("kom", dataObj.km, workspaceId);
		if (dataObj.gl) await setItem("gold", dataObj.gl, workspaceId);
		if (dataObj.ev) await setItem("evt", dataObj.ev, workspaceId);
		if (dataObj.dt) await setItem("dts", dataObj.dt, workspaceId);
		if (dataObj.settings) await setItem("settings", dataObj.settings);
		return {
			success: true,
			message: "داتاکانت لە ڕێگەی کۆدی کڵاودەوە بە سەرکەوتوویی گەڕێنرانەوە!",
			data: dataObj
		};
	} catch (err) {
		return {
			success: false,
			message: err?.message || "هەڵەیەک ڕوویدا لە کاتی هاوردەکردنی کۆدەکە"
		};
	}
};
