var exportExcelWorkbook = async (params) => {
	const { currentMonth, isYearly, isIncomeLocked, workspaceId, langIndex, monthNames, members, defaultRate } = params;
	const yearStr = currentMonth.slice(0, 4);
	const docs = [];
	if (isYearly) for (let m = 1; m <= 12; m++) {
		const mStr = `${yearStr}-${String(m).padStart(2, "0")}`;
		docs.push({
			label: monthNames[m - 1] || mStr,
			doc: await loadMonthDoc(mStr, workspaceId)
		});
	}
	else docs.push({
		label: currentMonth,
		doc: await loadMonthDoc(currentMonth, workspaceId)
	});
	const wb = utils.book_new();
	const sheet1Data = [[
		"Period",
		...isIncomeLocked ? [] : ["Income (IQD)"],
		"Expenses (IQD)",
		"Savings (IQD)",
		...isIncomeLocked ? [] : ["Remaining (IQD)", "Savings Rate (%)"]
	]];
	docs.forEach(({ label, doc }) => {
		const totals = calcMonthTotals(doc, defaultRate);
		sheet1Data.push([
			label,
			...isIncomeLocked ? [] : [Math.round(totals.inc)],
			Math.round(totals.exp),
			Math.round(totals.sv),
			...isIncomeLocked ? [] : [Math.round(totals.rem), Math.round(totals.savingsRate * 100)]
		]);
	});
	utils.book_append_sheet(wb, utils.aoa_to_sheet(sheet1Data), "Overview");
	const sheet2Data = [[
		"Date",
		"Category",
		"Amount",
		"Currency",
		"Amount (IQD)",
		"Person",
		"Shared",
		"Notes"
	]];
	docs.forEach(({ doc }) => {
		(doc.tx || []).forEach((tx) => {
			const catName = getCategoryName(tx.c, langIndex) || "Other";
			const personName = members[tx.w]?.n || "—";
			sheet2Data.push([
				tx.d,
				catName,
				tx.a,
				tx.cu === "U" ? "USD" : "IQD",
				Math.round(val(tx, defaultRate)),
				personName,
				tx.s ? "Yes" : "No",
				tx.n || ""
			]);
		});
	});
	utils.book_append_sheet(wb, utils.aoa_to_sheet(sheet2Data), "Expenses Log");
	const catTotals = Array(CATEGORIES.length).fill(0);
	docs.forEach(({ doc }) => {
		(doc.tx || []).forEach((tx) => {
			if (tx.c >= 0 && tx.c < CATEGORIES.length) catTotals[tx.c] += val(tx, defaultRate);
		});
	});
	const totalAllExp = sum(catTotals) || 1;
	const sheet3Data = [[
		"Category",
		"Total Spent (IQD)",
		"Share (%)"
	]];
	CATEGORIES.forEach((cat, idx) => {
		if (catTotals[idx] > 0) sheet3Data.push([
			getCategoryName(cat, langIndex) || "Other",
			Math.round(catTotals[idx]),
			+(catTotals[idx] / totalAllExp * 100).toFixed(1)
		]);
	});
	utils.book_append_sheet(wb, utils.aoa_to_sheet(sheet3Data), "Categories");
	const wbOut = writeSync(wb, {
		bookType: "xlsx",
		type: "array"
	});
	downloadFile(`expenses-${isYearly ? yearStr : currentMonth}.xlsx`, new Blob([wbOut], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" }));
};
