	if (rates.EUR) out.E = Math.round(usdToIqd / rates.EUR);
	if (rates.GBP) out.G = Math.round(usdToIqd / rates.GBP);
	if (rates.TRY) out.T = Math.round(usdToIqd / rates.TRY * 10) / 10;
