async function saveCloudBackup(backupId, workspaceName, payloadObj) {
	const user = auth.currentUser;
	if (!user) throw new Error("Not signed in");
	const safeId = backupId.replace(/[^a-zA-Z0-9_-]/g, "_").slice(0, 128) || "default_workspace";
	const serialized = JSON.stringify(payloadObj);
	if (serialized.length > 89e4) throw new Error("Backup size exceeds 900KB limit");
	const docRef = doc(db, "backups", safeId);
	try {
		if ((await getDoc(docRef)).exists()) await updateDoc(docRef, {
			workspaceName: workspaceName.slice(0, 100) || "پڕۆفایلی سەرەکی",
			payload: serialized,
			updatedAt: serverTimestamp()
		});
		else await setDoc(docRef, {
			ownerId: user.uid,
			workspaceName: workspaceName.slice(0, 100) || "پڕۆفایلی سەرەکی",
			payload: serialized,
			createdAt: serverTimestamp(),
			updatedAt: serverTimestamp()
		});
	} catch (error) {
		handleFirestoreError(error, "write", `backups/${safeId}`);
	}
}
async function listUserCloudBackups() {
	const user = auth.currentUser;
	if (!user) return [];
	try {
		return (await getDocs(query(collection(db, "backups"), where("ownerId", "==", user.uid)))).docs.map((d) => ({
			id: d.id,
			...d.data()
		}));
	} catch (error) {
		handleFirestoreError(error, "list", "backups");
	}
}
async function pushSharedFamilyWorkspace(inviteCode, workspaceName, payloadObj) {
	const user = auth.currentUser;
	if (!user) throw new Error("Not signed in");
	const cleanCode = inviteCode.trim().toUpperCase().replace(/[^A-Z0-9_-]/g, "");
	if (cleanCode.length < 4 || cleanCode.length > 32) throw new Error("کۆدی خێزان دەبێت لە ٤ بۆ ٣٢ پیت یان ژمارە پێکهاتبێت");
	const serialized = JSON.stringify(payloadObj);
	if (serialized.length > 89e4) throw new Error("Backup size exceeds 900KB limit");
	const docRef = doc(db, "shared_workspaces", cleanCode);
	try {
		if ((await getDoc(docRef)).exists()) await updateDoc(docRef, {
			workspaceName: workspaceName.slice(0, 100) || "خێزانی هاوبەش",
			payload: serialized,
			updatedBy: user.email || user.uid,
			updatedAt: serverTimestamp()
		});
		else await setDoc(docRef, {
			ownerId: user.uid,
			workspaceName: workspaceName.slice(0, 100) || "خێزانی هاوبەش",
			payload: serialized,
			updatedBy: user.email || user.uid,
			createdAt: serverTimestamp(),
			updatedAt: serverTimestamp()
		});
	} catch (error) {
		handleFirestoreError(error, "write", `shared_workspaces/${cleanCode}`);
	}
}
function subscribeSharedFamilyWorkspace(inviteCode, onData) {
	const cleanCode = inviteCode.trim().toUpperCase().replace(/[^A-Z0-9_-]/g, "");
	return onSnapshot(doc(db, "shared_workspaces", cleanCode), (snap) => {
		if (snap.exists()) {
			const data = snap.data();
			if (data?.payload) try {
				onData(JSON.parse(data.payload), data.updatedBy);
			} catch {}
		}
	}, (error) => {
		handleFirestoreError(error, "get", `shared_workspaces/${cleanCode}`);
	});
}
